import os
from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions
from azure.core.credentials import AzureKeyCredential
from document_models import SafetyResult

def ocr_safety(text: str, config=None) -> SafetyResult:
    if config is None:
        config = {}

    key = config.get('content_safety_api_key') or os.environ.get("AZURE_CONTENT_SAFETY_KEY")
    endpoint = config.get('content_safety_endpoint') or os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT")

    if not all([key, endpoint]):
        raise ValueError("Azure Content Safety API key and endpoint must be provided in config or environment variables.")

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))

    request = AnalyzeTextOptions(text=text)
    response = client.analyze_text(request)

    is_safe = True
    categories = {
        "Hate": {"severity": 0, "detected": False},
        "Sexual": {"severity": 0, "detected": False},
        "Violence": {"severity": 0, "detected": False},
        "SelfHarm": {"severity": 0, "detected": False},
    }

    for category_result in response.categories_analysis:
        category_name = category_result.category.value
        severity = category_result.severity
        if severity > 0:
            is_safe = False
            categories[category_name]["detected"] = True
            categories[category_name]["severity"] = severity

    return SafetyResult(is_safe=is_safe, categories=categories)

import io
from document_client import get_document_intelligence_client
from document_models import AnalyzeDocumentRequest, FieldExtractionResult

def document_field_extraction(payload: AnalyzeDocumentRequest, config=None) -> FieldExtractionResult:
    if config is None:
        config = {}

    model_id = payload.model_id # Expecting a custom model ID for field extraction
    if not model_id:
        raise ValueError("A custom model_id is required for document field extraction.")

    client = get_document_intelligence_client(config)
    with client:
        poller = client.begin_analyze_document(
            model_id,
            body=io.BytesIO(payload.document_bytes),
            content_type=payload.mime_type
        )
        result = poller.result()

    extracted_fields = {}
    if result.documents:
        # Assuming a single document for simplicity and taking the first one
        # Custom models provide fields under the 'fields' attribute of a document
        if result.documents[0].fields:
            for field_name, field_value in result.documents[0].fields.items():
                extracted_fields[field_name] = field_value.content if field_value.content else field_value.value

    return FieldExtractionResult(fields=extracted_fields)
